       be32_to_cpu(rsp->resp_data_len),
       min_t(int, be32_to_cpu(rsp->sense_data_len),
             SCSI_SENSE_BUFFERSIZE));
srp_process_rsp(ch, iu->buf);
Reason:
The function `srp_process_rsp` copies sense data using a source offset derived from `resp_data_len` (a 32-bit value supplied by the target) without verifying that the total length (header + response data + sense data) fits within the actual number of bytes received (`wc->byte_len`). An attacker can set `resp_data_len` to a very large value, causing the copy source to point far beyond the receive buffer, resulting in an out-of-bounds read. The calling code in `srp_recv_done` did not pass `wc->byte_len` to `srp_process_rsp`, so no length check could be performed.

The code statements that fix the bug are:
if (sizeof(*rsp) + (u64)resp_len + sense_len <= byte_len)
    memcpy(scmnd->sense_buffer,
           rsp->data + resp_len,
           min(sense_len, SCSI_SENSE_BUFFERSIZE));
else
    shost_printk(KERN_ERR, target->scsi_host,
                 "dropping truncated sense data (resp_data_len %u sense_data_len %u, %u bytes received)\n",
                 resp_len, sense_len, byte_len);
srp_process_rsp(ch, iu->buf, wc->byte_len);
Reason:
The fix adds a bounds check before copying sense data: the entire region (response header + response data + sense data) must fit into the received buffer size `byte_len`. If it does not, the sense data is dropped, and an error is logged, preventing the out-of-bounds read. Additionally, `srp_recv_done` now passes `wc->byte_len` to `srp_process_rsp` so that the validation can use the actual received length.

